MATCH (acl:S3Acl)-[:APPLIES_TO]->(bucket:S3Bucket)<-[:RESOURCE]-(aws:AWSAccount{id: $AWS_ID})<-[:OWNER]-(:AWSOrganization{id: $ORGANIZATION_ID})<-[:OWNER]-(:CloudanixWorkspace{id: $WORKSPACE_ID})
WHERE acl.uri IN ['http://acs.amazonaws.com/groups/global/AllUsers', 'http://acs.amazonaws.com/groups/global/AuthenticatedUsers'] AND acl.permission = 'READ' AND NOT coalesce(bucket.ignore_public_acls, false) AND NOT coalesce(aws.s3_ignore_public_acls, false)
SET bucket.anonymous_access = true, bucket.anonymous_actions = coalesce(bucket.anonymous_actions, []) + ['s3:ListBucket', 's3:ListBucketVersions', 's3:ListBucketMultipartUploads'],(CASE WHEN NOT 'acl' IN  coalesce(bucket.anonymous_access_type , []) THEN bucket END).anonymous_access_type = coalesce(bucket.anonymous_access_type , []) + 'acl';

MATCH (acl:S3Acl)-[:APPLIES_TO]->(bucket:S3Bucket)<-[:RESOURCE]-(aws:AWSAccount{id: $AWS_ID})<-[:OWNER]-(:AWSOrganization{id: $ORGANIZATION_ID})<-[:OWNER]-(:CloudanixWorkspace{id: $WORKSPACE_ID})
WHERE acl.uri IN ['http://acs.amazonaws.com/groups/global/AllUsers', 'http://acs.amazonaws.com/groups/global/AuthenticatedUsers'] AND acl.permission = 'READ_ACP' AND NOT coalesce(bucket.ignore_public_acls, false) AND NOT coalesce(aws.s3_ignore_public_acls, false)
SET bucket.anonymous_access = true, bucket.anonymous_actions = coalesce(bucket.anonymous_actions, []) + ['s3:DeleteObjectVersion'],(CASE WHEN NOT 'acl' IN  coalesce(bucket.anonymous_access_type , []) THEN bucket END).anonymous_access_type = coalesce(bucket.anonymous_access_type , []) + 'acl';

MATCH (acl:S3Acl)-[:APPLIES_TO]->(bucket:S3Bucket)<-[:RESOURCE]-(aws:AWSAccount{id: $AWS_ID})<-[:OWNER]-(:AWSOrganization{id: $ORGANIZATION_ID})<-[:OWNER]-(:CloudanixWorkspace{id: $WORKSPACE_ID})
WHERE acl.uri IN ['http://acs.amazonaws.com/groups/global/AllUsers', 'http://acs.amazonaws.com/groups/global/AuthenticatedUsers'] AND acl.permission = 'WRITE_ACP' AND NOT coalesce(bucket.ignore_public_acls, false) AND NOT coalesce(aws.s3_ignore_public_acls, false)
SET bucket.anonymous_access = true, bucket.anonymous_actions = coalesce(bucket.anonymous_actions, []) + ['s3:PutBucketAcl'],(CASE WHEN NOT 'acl' IN  coalesce(bucket.anonymous_access_type , []) THEN bucket END).anonymous_access_type = coalesce(bucket.anonymous_access_type , []) + 'acl';

MATCH (acl:S3Acl)-[:APPLIES_TO]->(bucket:S3Bucket)<-[:RESOURCE]-(aws:AWSAccount{id: $AWS_ID})<-[:OWNER]-(:AWSOrganization{id: $ORGANIZATION_ID})<-[:OWNER]-(:CloudanixWorkspace{id: $WORKSPACE_ID})
WHERE acl.uri IN ['http://acs.amazonaws.com/groups/global/AllUsers', 'http://acs.amazonaws.com/groups/global/AuthenticatedUsers'] AND acl.permission = 'FULL_CONTROL' AND NOT coalesce(bucket.ignore_public_acls, false) AND NOT coalesce(aws.s3_ignore_public_acls, false)
SET bucket.anonymous_access = true, bucket.anonymous_actions = coalesce(bucket.anonymous_actions, []) + ['s3:ListBucket', 's3:ListBucketVersions', 's3:ListBucketMultipartUploads', 's3:PutObject', 's3:DeleteObject', 's3:DeleteObjectVersion', 's3:PutBucketAcl'],(CASE WHEN NOT 'acl' IN  coalesce(bucket.anonymous_access_type , []) THEN bucket END).anonymous_access_type = coalesce(bucket.anonymous_access_type , []) + 'acl';
